    let inputs = journal
        .run_inputs(vb_core::RunId::new(100))?
        .ok_or("inputs not found before close")?;
    assert_eq!(inputs.input_digest(), expected_input_digest);
    assert_eq!(inputs.workflow_digest(), expected_workflow_digest);
