        .workflow_source(inputs.source_digest())?
        .ok_or("source not found before close")?;
    let header = journal
        .run_header(vb_core::RunId::new(100))?
        .ok_or("header not found before close")?;
    let events = journal.events_for_run(vb_core::RunId::new(100))?;
