//! Raw journal snapshot test support for F1 duplicate and F2 reopen full-state checks.

use crate::FjallJournal;

type Rows = Vec<(Vec<u8>, Vec<u8>)>;
type Snapshot = [Rows; 8];

fn iterate_keyspace(journal: &FjallJournal, prefix: &[u8]) -> Result<Rows, Box<dyn std::error::Error>> {
    let prefix_owned = prefix.to_vec();
    let result: Rows = journal
        .iter(prefix_owned)?
        .enumerate()
        .map(|(i, guard)| {
            if i >= 16 {
                return Err("keyspace exceeds 16-row bound".to_string());
            }
            let (key, value) = guard.into_inner().map_err(|e| format!("into_inner: {e}"))?;
            Ok((key.to_vec(), value.to_vec()))
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(result)
}

fn iterate_single_keyspace(
    journal: &FjallJournal,
    prefix: &[u8],
) -> Result<Rows, Box<dyn std::error::Error>> {
    iterate_keyspace(journal, prefix)
}

pub(super) fn snapshot_journal(
    journal: &FjallJournal,
) -> Result<Snapshot, Box<dyn std::error::Error>> {
    let artifact_acceptance = iterate_single_keyspace(journal, b"")?;
    assert!(artifact_acceptance.len() <= 16, "artifact_acceptance exceeds bound");

    let workflow_source = iterate_single_keyspace(journal, b"")?;
    assert!(workflow_source.len() <= 16, "workflow_source exceeds bound");

    let compiled_ir = iterate_single_keyspace(journal, b"")?;
    assert!(compiled_ir.len() <= 16, "compiled_ir exceeds bound");

    let run_header = iterate_single_keyspace(journal, b"")?;
    assert!(run_header.len() <= 16, "run_header exceeds bound");

    let run_inputs = iterate_single_keyspace(journal, b"")?;
    assert!(run_inputs.len() <= 16, "run_inputs exceeds bound");

    let events = iterate_single_keyspace(journal, b"")?;
    assert!(events.len() <= 16, "events exceeds bound");

    let index_status = iterate_single_keyspace(journal, b"")?;
    assert!(index_status.len() <= 16, "index_status exceeds bound");

    let index_workflow = iterate_single_keyspace(journal, b"")?;
    assert!(index_workflow.len() <= 16, "index_workflow exceeds bound");

    Ok([
        artifact_acceptance,
        workflow_source,
        compiled_ir,
        run_header,
        run_inputs,
        events,
        index_status,
        index_workflow,
    ])
}

impl PartialEq for Snapshot {
    fn eq(&self, other: &Snapshot) -> bool {
        self[0] == other[0]
            && self[1] == other[1]
            && self[2] == other[2]
            && self[3] == other[3]
            && self[4] == other[4]
            && self[5] == other[5]
            && self[6] == other[6]
            && self[7] == other[7]
    }
}

